using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Reflection;
using Planner.Desktop;
using Planner.Core;
static class DateTimeChecks
{
 public static async Task Run(MainWindow main,PlannerViewModel vm,string directory,Action<bool,string> check)
 {
  var entry=new TimeEntry("23:59"){DateContext=new(2028,2,28)};var date=new StyledDateEntry{SelectedDate=new(2028,2,28)};var panel=new StackPanel{Margin=new(18)};panel.Children.Add(date);panel.Children.Add(entry);var w=new Window{Title="日期时间控件检查",Width=440,Height=240,Owner=main,Content=panel,WindowStartupLocation=WindowStartupLocation.CenterOwner};w.Show();await Task.Delay(50);
  var field=typeof(TimeEntry).GetField("popup",BindingFlags.Instance|BindingFlags.NonPublic)!;entry.OpenPicker();await Task.Delay(50);var popup=(Popup)field.GetValue(entry)!;var picker=Walk(popup.Child).OfType<TimeWheelPicker>().Single();Capture((FrameworkElement)popup.Child,System.IO.Path.Combine(directory,"time-picker.png"));var wheels=Walk(picker).OfType<TimeWheel>().ToArray();wheels[1].RollBy(1);check(picker.Value==new DateTime(2028,2,29,0,0,0)&&entry.Text=="23:59","时间滚轮分钟跨午夜携带日期且确认前不写入");Button(picker,"取消").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));check(!popup.IsOpen&&entry.DateContext==new DateTime(2028,2,28),"取消时间选择恢复原始日期和时间");
  entry.OpenPicker();popup=(Popup)field.GetValue(entry)!;picker=Walk(popup.Child).OfType<TimeWheelPicker>().Single();Walk(picker).OfType<TimeWheel>().Last().RollBy(1);Button(picker,"确定时间").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));check(entry.Text=="00:00"&&entry.DateContext==new DateTime(2028,2,29),"确认循环时间同时提交完整日期");
  date.OpenPicker();await Task.Delay(50);var datePopup=(Popup)typeof(StyledDateEntry).GetField("picker",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(date)!;Capture((FrameworkElement)datePopup.Child,System.IO.Path.Combine(directory,"date-picker.png"));var calendar=Walk(datePopup.Child).OfType<System.Windows.Controls.Calendar>().Single();calendar.SelectedDate=new(2028,3,1);check(date.SelectedDate==new DateTime(2028,2,28),"日期选择确认前保留原值");Button(datePopup.Child,"取消").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));check(date.SelectedDate==new DateTime(2028,2,28),"取消日期选择不修改原值");Typography.Apply(22);entry.OpenPicker();await Task.Delay(50);popup=(Popup)field.GetValue(entry)!;Capture((FrameworkElement)popup.Child,System.IO.Path.Combine(directory,"time-picker-large.png"));check(((FrameworkElement)popup.Child).ActualHeight<=SystemParameters.WorkArea.Height,"大字号时间弹窗可在屏幕工作区内滚动操作");Walk(popup.Child).OfType<Button>().First(b=>Equals(b.Content,"取消")).RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Typography.Apply(vm.Appearance.FontSize);w.Close();
  var editor=new EditorWindow(vm,null,new(2026,10,28,23,30,0)){Owner=main};editor.Show();await Task.Delay(50);var start=Walk(editor).OfType<TimeEntry>().Single(e=>Equals(e.Tag,"StartTime"));var end=Walk(editor).OfType<TimeEntry>().Single(e=>Equals(e.Tag,"EndTime"));start.Text="23:45";check(end.Text=="00:45"&&editor.DurationText.Contains("60 分钟"),"修改开始时间保持原耗时并联动跨日结束");start.DateContext=new(2026,10,29);start.Text="00:15";check(end.Text=="01:15"&&Walk(editor).OfType<DatePicker>().Single(d=>Equals(d.Tag,"EndDate")).SelectedDate==new DateTime(2026,10,29),"滚轮进位日期进入编辑器并保留时长");editor.Close();
 }
 static IEnumerable<DependencyObject> Walk(DependencyObject root){yield return root;foreach(var c in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var d in Walk(c))yield return d;}
 static Button Button(DependencyObject root,string name)=>Walk(root).OfType<Button>().First(b=>Equals(b.Content,name));
 static void Capture(FrameworkElement e,string path){e.UpdateLayout();var image=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Math.Ceiling(e.ActualWidth),(int)Math.Ceiling(e.ActualHeight),96,96,System.Windows.Media.PixelFormats.Pbgra32);image.Render(e);var png=new System.Windows.Media.Imaging.PngBitmapEncoder();png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(image));using var file=System.IO.File.Create(path);png.Save(file);}
}
